from typing import List

def rankTeams(votes: List[str]) -> str:
    # Create a dictionary to store the count of each rank for each team
    rank_count = {team: [0] * len(votes[0]) for team in votes[0]}

    # Count the ranks for each team
    for vote in votes:
        for i, team in enumerate(vote):
            rank_count[team][i] -= 1  # Use negative counts for max-heap behavior

    # Sort the teams based on the ranking system
    sorted_teams = sorted(votes[0], key=lambda team: rank_count[team])

    # Join the sorted teams into a single string
    return ''.join(sorted_teams)
